<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\InventoryService;

Auth::requirePermission('inventory.manage');$tenantId=em_require_tenant();$service=new InventoryService();
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');$productId=(int)($_POST['product_id']??0);$reason=trim((string)($_POST['reason']??''));
    try{
        if($action==='move'){$type=(string)($_POST['type']??'');$qty=(float)str_replace(',','.',(string)($_POST['quantity']??'0'));$costRaw=trim((string)($_POST['unit_cost']??''));$unitCost=$costRaw===''?null:(int)round((float)str_replace(',','.',$costRaw)*100);$result=$service->move($productId,$type,$qty,$reason,$type==='in'?$unitCost:null);em_flash('ok','Movimentação registrada. Custo médio atual: '.em_money((int)($result['average_cost_cents']??0)).'.');}
        elseif($action==='adjust'){$qty=(float)str_replace(',','.',(string)($_POST['new_quantity']??'0'));$service->setStock($productId,$qty,$reason);em_flash('ok','Saldo disponível ajustado. As unidades reservadas não foram alteradas.');}
        else throw new RuntimeException('Ação inválida.');
    }catch(Throwable $e){em_flash('error',$e->getMessage());}
    em_go('inventory');
}

$p=$pdo->prepare('SELECT p.id,p.name,p.sku,p.stock_qty,p.average_cost_cents,p.active,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=p.tenant_id AND sr.product_id=p.id AND sr.status="reserved"),0) reserved_qty FROM products p WHERE p.tenant_id=? AND p.track_stock=1 ORDER BY p.active DESC,p.name');$p->execute([$tenantId]);$products=$p->fetchAll();
$low=[];$reservedTotal=0.0;foreach($products as $row){if((float)$row['stock_qty']<=5)$low[]=$row;$reservedTotal+=(float)$row['reserved_qty'];}
$m=$pdo->prepare('SELECT sm.*,p.name product_name,p.sku,o.id linked_order FROM stock_movements sm JOIN products p ON p.id=sm.product_id LEFT JOIN orders o ON o.id=sm.order_id WHERE sm.tenant_id=? ORDER BY sm.id DESC LIMIT 200');$m->execute([$tenantId]);$movements=$m->fetchAll();
$r=$pdo->prepare('SELECT sr.*,p.name product_name,o.status order_status,o.payment_status FROM stock_reservations sr JOIN products p ON p.id=sr.product_id JOIN orders o ON o.id=sr.order_id WHERE sr.tenant_id=? AND sr.status="reserved" ORDER BY sr.id DESC LIMIT 150');$r->execute([$tenantId]);$reservations=$r->fetchAll();
$selected=(int)($_GET['product_id']??0);
em_header('Estoque','inventory');
?><div class="alert" style="margin-bottom:18px"><strong>Como funciona:</strong> o saldo <b>disponível</b> já desconta unidades reservadas por pedidos. Entradas podem informar custo unitário; o EventMenu recalcula o <b>custo médio ponderado</b>. Ao pagar, a reserva vira saída definitiva; ao cancelar ou expirar, a quantidade volta automaticamente.</div>
<section class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))"><div class="card metric"><span class="muted">Produtos controlados</span><strong><?= count($products) ?></strong></div><div class="card metric"><span class="muted">Estoque disponível baixo / zerado</span><strong><?= count($low) ?></strong></div><div class="card metric"><span class="muted">Unidades reservadas</span><strong><?= Security::e((string)$reservedTotal) ?></strong></div></section>
<div class="grid" style="grid-template-columns:minmax(300px,1fr) minmax(0,2fr);margin-top:18px"><section class="card"><h2>Movimentar estoque</h2><?php if(!$products):?><p class="muted">Nenhum produto com controle de estoque ativo.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="move"><label class="span-2">Produto<select name="product_id" required><?php foreach($products as $p):?><option value="<?= (int)$p['id'] ?>"<?= em_selected($selected,$p['id']) ?>><?= Security::e($p['name'].($p['sku']?' · '.$p['sku']:'').' · disponível '.$p['stock_qty'].' · custo médio '.em_money((int)$p['average_cost_cents'])) ?></option><?php endforeach;?></select></label><label>Tipo<select name="type"><option value="in">Entrada / compra</option><option value="out">Saída</option></select></label><label>Quantidade<input name="quantity" inputmode="decimal" required></label><label class="span-2">Custo unitário da entrada<input name="unit_cost" inputmode="decimal" placeholder="Ex.: 3,75"><small>Usado apenas em entradas. Deixe em branco quando não houver custo de compra.</small></label><label class="span-2">Motivo<textarea name="reason" required maxlength="500" placeholder="Compra de fornecedor, perda, consumo interno..."></textarea></label><button class="primary span-2">Registrar movimento</button></form><hr style="border-color:var(--line);margin:24px 0"><h3>Ajuste de saldo disponível</h3><p class="muted">Informe somente o que está livre para nova venda. O custo médio não é alterado por ajuste de contagem.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="adjust"><label class="span-2">Produto<select name="product_id" required><?php foreach($products as $p):?><option value="<?= (int)$p['id'] ?>"<?= em_selected($selected,$p['id']) ?>><?= Security::e($p['name'].' · disponível '.$p['stock_qty'].' · reservado '.$p['reserved_qty']) ?></option><?php endforeach;?></select></label><label class="span-2">Novo saldo disponível<input name="new_quantity" inputmode="decimal" required></label><label class="span-2">Motivo do ajuste<textarea name="reason" required maxlength="500"></textarea></label><button class="secondary span-2">Ajustar saldo disponível</button></form><?php endif;?></section><section class="card"><div class="section-head"><h2>Saldos e custos</h2><span class="muted">custo médio ponderado</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Disponível</th><th>Reservado</th><th>Total físico</th><th>Custo médio</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as $p):$available=(float)$p['stock_qty'];$reserved=(float)$p['reserved_qty'];$physical=$available+$reserved;?><tr><td><strong><?= Security::e($p['name']) ?></strong><br><span class="muted"><?= Security::e($p['sku']??'Sem SKU') ?></span></td><td><strong><?= Security::e((string)$p['stock_qty']) ?></strong></td><td><?= Security::e((string)$p['reserved_qty']) ?></td><td><?= Security::e((string)$physical) ?></td><td><strong><?= em_money((int)$p['average_cost_cents']) ?></strong></td><td><span class="badge"><?= $available<=0?'Zerado':($available<=5?'Baixo':'OK') ?></span></td><td><a class="button secondary" href="<?= Security::e(app_url('?route=inventory&product_id='.(int)$p['id'])) ?>">Movimentar</a></td></tr><?php endforeach;?></tbody></table></div></section></div>
<section class="card" style="margin-top:18px"><div class="section-head"><h2>Reservas ativas</h2><span class="muted">pedidos ainda não convertidos em saída definitiva</span></div><?php if(!$reservations):?><p class="muted">Nenhuma unidade reservada no momento.</p><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Pedido</th><th>Produto</th><th>Qtd.</th><th>Pedido</th><th>Pagamento</th><th>Expira</th></tr></thead><tbody><?php foreach($reservations as $res):?><tr><td>#<?= (int)$res['order_id'] ?></td><td><?= Security::e($res['product_name']) ?></td><td><?= Security::e((string)$res['quantity']) ?></td><td><span class="badge"><?= Security::e($res['order_status']) ?></span></td><td><span class="badge"><?= Security::e($res['payment_status']) ?></span></td><td><?= Security::e($res['expires_at']??'Até pagamento/cancelamento') ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="card" style="margin-top:18px"><div class="section-head"><h2>Últimas movimentações</h2><span class="muted">quantidade e valor de custo</span></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Produto</th><th>Tipo</th><th>Qtd.</th><th>Custo un.</th><th>Custo total</th><th>Pedido</th><th>Data</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td>#<?= (int)$m['id'] ?></td><td><?= Security::e($m['product_name']) ?></td><td><span class="badge"><?= Security::e($m['type']) ?></span></td><td><?= Security::e((string)$m['quantity']) ?></td><td><?= $m['unit_cost_cents']!==null?em_money((int)$m['unit_cost_cents']):'—' ?></td><td><?= $m['total_cost_cents']!==null?em_money(abs((int)$m['total_cost_cents'])):'—' ?></td><td><?= $m['linked_order']?'#'.(int)$m['linked_order']:'Manual' ?></td><td><?= Security::e($m['created_at']??'') ?></td></tr><?php endforeach;?></tbody></table></div></section><?php em_footer();
